/* ══════════════════════════════════════════════════════════════════
   Flourish entitlement — auth, membership state, purchase restore.

   WHY THIS EXISTS: before this module the paywall was `S.unlocked` in
   localStorage, flipped by a `?sub=success` query param. Anyone could type
   that URL and unlock 1,095 days for free, and a real buyer who reinstalled
   lost everything. App Store review rejects both (3.1.1 requires working
   Restore Purchases). Entitlement is now proven server-side against a
   signed identity and cached only as a convenience.
   ══════════════════════════════════════════════════════════════════ */

const AUTH_KEY = "flourish_auth";
let CFG = null;

/* ---- public config (no keys baked into the bundle) ---- */
async function flourishConfig(){
  if (CFG) return CFG;
  try {
    const r = await fetch(FLOURISH_API + "/api/public-config");
    if (r.ok) { CFG = await r.json(); localStorage.setItem("flourish_cfg", JSON.stringify(CFG)); return CFG; }
  } catch (e) { /* offline */ }
  try { CFG = JSON.parse(localStorage.getItem("flourish_cfg") || "null"); } catch (e) { CFG = null; }
  return CFG;
}

/* ---- session ---- */
function authSession(){ try { return JSON.parse(localStorage.getItem(AUTH_KEY) || "null"); } catch (e) { return null; } }
function setAuthSession(s){ s ? localStorage.setItem(AUTH_KEY, JSON.stringify(s)) : localStorage.removeItem(AUTH_KEY); }
function authEmail(){ const s = authSession(); return (s && s.email) || ""; }
function isSignedIn(){ const s = authSession(); return !!(s && s.access_token); }
/* The signed-in user's id: the JWT's `sub`. Rows whose RLS check is
   `user_id = auth.uid()` (prayer_requests, messages) have no column default,
   so the client must send it; leaving it out failed every insert. */
function authUserId(){
  const s = authSession();
  if (!s || !s.access_token) return "";
  try {
    const part = s.access_token.split(".")[1] || "";
    const json = atob(part.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((part.length + 3) % 4));
    return (JSON.parse(json).sub) || "";
  } catch (err) { return ""; }
}

async function authToken(){
  const s = authSession();
  if (!s || !s.access_token) return "";
  if (s.expires_at && Date.now() / 1000 > s.expires_at - 60) {
    const cfg = await flourishConfig();
    if (!cfg || !s.refresh_token) return "";
    try {
      const r = await fetch(cfg.supabase_url + "/auth/v1/token?grant_type=refresh_token", {
        method: "POST",
        headers: { "Content-Type": "application/json", apikey: cfg.supabase_anon_key },
        body: JSON.stringify({ refresh_token: s.refresh_token })
      });
      if (!r.ok) { setAuthSession(null); return ""; }
      const j = await r.json();
      setAuthSession({ access_token: j.access_token, refresh_token: j.refresh_token,
                       expires_at: j.expires_at, email: (j.user && j.user.email) || s.email });
      return j.access_token;
    } catch (e) { return ""; }
  }
  return s.access_token;
}

/* ---- magic-link sign-in (no password to leak, no extra PII) ---- */
async function sendMagicLink(email){
  const cfg = await flourishConfig();
  if (!cfg || !cfg.supabase_url) { toast("⚠ Sign-in unavailable right now"); return false; }
  const r = await fetch(cfg.supabase_url + "/auth/v1/otp", {
    method: "POST",
    headers: { "Content-Type": "application/json", apikey: cfg.supabase_anon_key },
    body: JSON.stringify({ email, create_user: true,
      options: { email_redirect_to: location.origin + location.pathname } })
  });
  return r.ok;
}

/* One place that stores a session, whichever way it arrived. */
function storeSession(j, fallbackEmail){
  setAuthSession({
    access_token:  j.access_token,
    refresh_token: j.refresh_token || "",
    expires_at:    j.expires_at ||
                   Math.floor(Date.now()/1000) + parseInt(j.expires_in || "3600", 10),
    email: (j.user && j.user.email) || fallbackEmail || ""
  });
}

/* The six-digit code. Same one-time token that backs the magic link, verified
   directly — which is what makes sign-in work inside the iOS shell, where
   tapping a link in Mail opens Safari and the app never sees the session. */
async function verifyEmailCode(email, code){
  const cfg = await flourishConfig();
  if (!cfg || !cfg.supabase_url) return { ok:false, error:"Sign-in unavailable right now" };
  try {
    const r = await fetch(cfg.supabase_url + "/auth/v1/verify", {
      method: "POST",
      headers: { "Content-Type": "application/json", apikey: cfg.supabase_anon_key },
      body: JSON.stringify({ email: email, token: String(code).trim(), type: "email" })
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || !j.access_token) {
      return { ok:false, error: j.error_description || j.msg || "That code didn't work" };
    }
    storeSession(j, email);
    return { ok:true };
  } catch (e) { return { ok:false, error:"Couldn't reach the sign-in service" }; }
}

/* Supabase returns the session in the URL fragment after the magic link. */
(function captureMagicLinkReturn(){
  if (!location.hash.includes("access_token=")) return;
  const p = new URLSearchParams(location.hash.replace(/^#/, ""));
  const at = p.get("access_token");
  if (!at) return;
  /* The email is in the token's own payload. Storing "" here meant the account
     card said "signed in" instead of the address the member typed. */
  let mail = "";
  try { mail = JSON.parse(atob(at.split(".")[1].replace(/-/g,"+").replace(/_/g,"/"))).email || ""; }
  catch (e) {}
  setAuthSession({
    access_token: at, refresh_token: p.get("refresh_token") || "",
    expires_at: Math.floor(Date.now() / 1000) + parseInt(p.get("expires_in") || "3600", 10),
    email: mail
  });
  history.replaceState(null, "", location.pathname);
  setTimeout(async () => {
    await refreshUnlock();
    // board item 4: a returning member's three years live on the server, not this device
    if (typeof restoreProgress === "function") await restoreProgress();
    toast("Signed in ✓");
    if (window.render) render();
  }, 300);
})();

